class Solution:
    def maxXorString(self, s, t):
        z = t.count('0')
        o = len(t) - z
        res = []
        for c in s:
            if c == '1':
                if z > 0:
                    res.append('0'); z -= 1
                else:
                    res.append('1'); o -= 1
            else:
                if o > 0:
                    res.append('1'); o -= 1
                else:
                    res.append('0'); z -= 1
        return ''.join(res)

