class Solution {
public:
    string maxXorString(string s, string t) {
        int z = count(t.begin(), t.end(), '0'), o = t.size() - z;
        string res;
        for (char c : s) {
            if (c == '1') {
                if (z > 0) { res += '0'; z--; }
                else { res += '1'; o--; }
            } else {
                if (o > 0) { res += '1'; o--; }
                else { res += '0'; z--; }
            }
        }
        return res;
    }
};

