class Solution:
    def maxXorString(self, s, t):
        n = len(s)
        ones = t.count('1')
        tp = ['0'] * n
        for i in range(n):
            if ones and s[i] == '0':
                tp[i] = '1'; ones -= 1
        for i in range(n):
            if ones and tp[i] == '0':
                tp[i] = '1'; ones -= 1
        return ''.join('1' if s[i] != tp[i] else '0' for i in range(n))

