class Solution {
    public String maxXorString(String s, String t) {
        int n = s.length(), ones = 0;
        for (char c : t.toCharArray()) if (c == '1') ones++;
        char[] tp = new char[n];
        java.util.Arrays.fill(tp, '0');
        for (int i = 0; i < n && ones > 0; i++)
            if (s.charAt(i) == '0') { tp[i] = '1'; ones--; }
        for (int i = 0; i < n && ones > 0; i++)
            if (tp[i] == '0') { tp[i] = '1'; ones--; }
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) res.append(s.charAt(i) != tp[i] ? '1' : '0');
        return res.toString();
    }
}

